// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/session", wrapper.Logout)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/session", wrapper.GetSession)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/session", wrapper.Login)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me/assignments", wrapper.ListMyAssignments)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me/assignments/{assignmentId}", wrapper.GetMyAssignment)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me/assignments/{assignmentId}/files/{fileId}", wrapper.DownloadMyAssignmentFile)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me/assignments/{assignmentId}/submission", wrapper.DownloadMySubmission)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/me/assignments/{assignmentId}/submission", wrapper.UploadMySubmission)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/classes", wrapper.ListClasses)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/classes", wrapper.CreateClass)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/classes/{classId}/students", wrapper.ListClassStudents)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/students", wrapper.CreateStudent)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/students/{studentId}", wrapper.DeleteStudent)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/students/{studentId}", wrapper.UpdateStudent)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/students/{studentId}/password", wrapper.SetStudentPassword)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/assignments", wrapper.ListAssignments)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/assignments", wrapper.CreateAssignment)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/assignments/{assignmentId}", wrapper.DeleteAssignment)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/assignments/{assignmentId}", wrapper.GetAssignment)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/assignments/{assignmentId}", wrapper.UpdateAssignment)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/assignments/{assignmentId}/files", wrapper.UploadAssignmentFile)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/assignments/{assignmentId}/files/{fileId}", wrapper.DeleteAssignmentFile)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/assignments/{assignmentId}/files/{fileId}", wrapper.DownloadAssignmentFile)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/assignments/{assignmentId}/classes/{classId}", wrapper.SetClassDeadline)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/assignments/{assignmentId}/classes/{classId}/submissions", wrapper.ListClassSubmissions)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/assignments/{assignmentId}/submissions/{studentId}/file", wrapper.DownloadSubmission)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/assignments/{assignmentId}/submissions/{studentId}/status", wrapper.SetSubmissionStatus)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/assignments/{assignmentId}/submissions/{studentId}/score", wrapper.SetSubmissionScore)

	return m
}

